window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-8d0b02699e9ce989"]={"versions": [{"id": "FIG-8d0b02699e9ce989", "releases": ["R20-11", "R21-11", "R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR-Konfigurationsmetamodells (ECU Configuration Parameter Definition, EcuC) im Kontext der BSW-Verteilung (BSW Distribution Guide). Dargestellt ist das Schema zur Zuordnung von Software-Komponenten-Instanzen und BSW-Partitionen zu <code>EcucPartition</code>-Containern sowie deren Verknüpfung mit OS-Applikationen (<code>OsApplication</code>) und Multi-Core-Definitionen (<code>EcucCoreDefinition</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>EcuC: EcucModuleDef</strong> (Multiplizität: 0..1): Wurzel-Moduldefinition.</li>\n<li>Komposition <code>+container</code> zu <strong>EcucPartitionCollection: EcucParamConfContainerDef</strong> (Multiplizität: 0..1).</li>\n<li><strong>EcucPartitionCollection</strong>: Enthält per Komposition <code>+subContainer</code> <strong>EcucPartition: EcucParamConfContainerDef</strong> (Multiplizität: 0..*).</li>\n<li><strong>EcucPartition</strong>: Repräsentiert eine logische Partition.</li>\n<li>Enthält Parameter <code>+parameter</code> <strong>PartitionCanBeRestarted: EcucBooleanParamDef</strong>.</li>\n<li>Enthält Parameter <code>+parameter</code> <strong>EcucDefaultBswPartition: EcucBooleanParamDef</strong> (Multiplizität: 0..1).</li>\n<li>Enthält Referenz <code>+reference</code> <strong>EcucPartitionBswModuleDistinguishedPartition: EcucForeignReferenceDef</strong> (Multiplizität: 0..*, Zieltyp: <code>BSW-DISTINGUISHED-PARTITION</code>), referenziert <code>BswDistinguishedPartition</code> (<code>Referrable</code> aus dem BSW Module Description Template).</li>\n<li>Enthält Instanzreferenz <code>+reference</code> <strong>EcucPartitionSoftwareComponentInstanceRef: EcucInstanceReferenceDef</strong> (Multiplizität: 0..*, Zieltyp: <code>SW-COMPONENT-PROTOTYPE</code>, Zielkontext: <code>ROOT-SW-COMPOSITION-PROTOTYPE</code>), referenziert <code>SwComponentPrototype</code> (<code>AtpPrototype</code> aus dem SW Component Template).</li>\n<li><strong>OsApplication: EcucParamConfContainerDef</strong> (Multiplizität: 0..*): Betriebssystem-Applikationscontainer.</li>\n<li>Enthält Referenz <code>+reference</code> <strong>OsAppEcucPartitionRef: EcucReferenceDef</strong> (Multiplizität: 0..1) mit Ziel <code>+destination</code> auf <code>EcucPartition</code>.</li>\n<li>Enthält Referenz <code>+reference</code> <strong>OsApplicationCoreRef: EcucReferenceDef</strong> (Multiplizität: 0..1) mit Ziel <code>+destination</code> auf <code>EcucCoreDefinition</code>.</li>\n<li><strong>EcucCoreDefinition: EcucParamConfContainerDef</strong> (Multiplizität: 0..*):</li>\n<li>Enthält Parameter <code>+parameter</code> <strong>EcucCoreId: EcucIntegerParamDef</strong> (Wertebereich: min = 0, max = 65535).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Konfigurations-Metamodell ohne dynamische Ausführungssemantik oder Laufzeitsequenzen. Definiert Deklarationsstrukturen zur Entwurfs- und Generierungszeit für das Mapping von BSW- und SWC-Anteilen auf Partitionen, OS-Applikationen und Prozessorkerne.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Das Metamodell steuert die Generierung der RTE- und OS-Konfiguration bei verteilten BSW-Architekturen.</li>\n<li>Über <code>EcucPartitionBswModuleDistinguishedPartition</code> werden BSW-Module bzw. deren unterscheidbare Partitionen spezifischen Partitionen zugeordnet.</li>\n<li>Über <code>EcucPartitionSoftwareComponentInstanceRef</code> erfolgt die Zuordnung konkreter Instanzen von <code>SwComponentPrototype</code> auf Partitions-Ebene im Kontext des Root-Composition-Prototyps.</li>\n<li>Die Beziehung zwischen OS und EcuC-Partitionen erfolgt über <code>OsAppEcucPartitionRef</code> (0..1), wodurch eine OS-Applikation maximal einer Partition zugeordnet ist.</li>\n<li>Die Zuordnung der OS-Applikation zu einem Prozessorkern wird direkt über die Referenz <code>OsApplicationCoreRef</code> auf eine <code>EcucCoreDefinition</code> abgebildet.</li>\n</ul>"}, {"id": "FIG-ae83011d4a502d37", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR-Konfigurationsmetamodells (ECU Configuration Parameter Definition, EcuC) im Kontext der BSW-Verteilung (BSW Distribution Guide). Dargestellt ist das Schema zur Zuordnung von Software-Komponenten-Instanzen und BSW-Partitionen zu <code>EcucPartition</code>-Containern sowie deren Verknüpfung mit OS-Applikationen (<code>OsApplication</code>) und Multi-Core-Definitionen (<code>EcucCoreDefinition</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>EcuC: EcucModuleDef</strong> (Multiplizität: 0..1): Wurzel-Moduldefinition.</li>\n<li>Komposition <code>+container</code> zu <strong>EcucPartitionCollection: EcucParamConfContainerDef</strong> (Multiplizität: 0..1).</li>\n<li><strong>EcucPartitionCollection</strong>: Enthält per Komposition <code>+subContainer</code> <strong>EcucPartition: EcucParamConfContainerDef</strong> (Multiplizität: 0..*).</li>\n<li><strong>EcucPartition</strong>: Repräsentiert eine logische Partition.</li>\n<li>Enthält Parameter <code>+parameter</code> <strong>PartitionCanBeRestarted: EcucBooleanParamDef</strong>.</li>\n<li>Enthält Parameter <code>+parameter</code> <strong>EcucDefaultBswPartition: EcucBooleanParamDef</strong> (Multiplizität: 0..1).</li>\n<li>Enthält Referenz <code>+reference</code> <strong>EcucPartitionBswModuleDistinguishedPartition: EcucForeignReferenceDef</strong> (Multiplizität: 0..*, Zieltyp: <code>BSW-DISTINGUISHED-PARTITION</code>), referenziert <code>BswDistinguishedPartition</code> (<code>Referrable</code> aus dem BSW Module Description Template).</li>\n<li>Enthält Instanzreferenz <code>+reference</code> <strong>EcucPartitionSoftwareComponentInstanceRef: EcucInstanceReferenceDef</strong> (Multiplizität: 0..*, Zieltyp: <code>SW-COMPONENT-PROTOTYPE</code>, Zielkontext: <code>ROOT-SW-COMPOSITION-PROTOTYPE</code>), referenziert <code>SwComponentPrototype</code> (<code>AtpPrototype</code> aus dem SW Component Template).</li>\n<li><strong>OsApplication: EcucParamConfContainerDef</strong> (Multiplizität: 0..*): Betriebssystem-Applikationscontainer.</li>\n<li>Enthält Referenz <code>+reference</code> <strong>OsAppEcucPartitionRef: EcucReferenceDef</strong> (Multiplizität: genau 1..1) mit Ziel <code>+destination</code> auf <code>EcucPartition</code>.</li>\n<li><strong>EcucCoreDefinition: EcucParamConfContainerDef</strong> (Multiplizität: 1..*):</li>\n<li>Enthält Parameter <code>+parameter</code> <strong>EcucCoreId: EcucIntegerParamDef</strong> (Wertebereich: min = 0, max = 65535).</li>\n<li>Es besteht keine direkte Modellreferenz zwischen <code>OsApplication</code> und <code>EcucCoreDefinition</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Konfigurations-Metamodell ohne dynamische Ausführungssemantik oder Laufzeitsequenzen. Definiert Deklarationsstrukturen zur Entwurfs- und Generierungszeit für das Mapping von BSW- und SWC-Anteilen auf Partitionen, OS-Applikationen und Prozessorkerne.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Jede <code>OsApplication</code> muss über <code>OsAppEcucPartitionRef</code> verbindlich genau einer <code>EcucPartition</code> zugeordnet sein (Multiplizität 1..1).</li>\n<li>Mindestens ein <code>EcucCoreDefinition</code>-Container muss konfiguriert werden (<code>lowerMultiplicity = 1</code>).</li>\n<li>Eine direkte Bindung von <code>OsApplication</code> an <code>EcucCoreDefinition</code> existiert in diesem Metamodellausschnitt nicht; die Zuweisung erfolgt indirekt oder über andere Spezifikationsebenen.</li>\n<li><code>EcucPartitionBswModuleDistinguishedPartition</code> und <code>EcucPartitionSoftwareComponentInstanceRef</code> definieren die BSW- bzw. SWC-Partitionierung weiterhin wie spezifiziert.</li>\n</ul>"}, {"id": "FIG-8a1b20c062d31ec3", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR-Konfigurationsmetamodells (EcuC) für Core-Definitionen. Das Diagramm beschreibt isoliert die Definition logischer Prozessorkerne im EcuC-Konfigurationsschema.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>EcucCoreDefinition: EcucParamConfContainerDef</strong> (Multiplizität: 1..*): Container für Prozessorkern-Definitionen.</li>\n<li>Enthält Parameter <code>+parameter</code> <strong>EcucCoreId: EcucIntegerParamDef</strong> (Multiplizität 1, Wertebereich: min = 0, max = 65535) zur Identifikation des Prozessorkerns.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Konfigurations-Metamodell ohne dynamische Ausführungssemantik oder Laufzeitsequenzen. Definiert Deklarationsstrukturen zur Entwurfs- und Generierungszeit für das Mapping von BSW- und SWC-Anteilen auf Partitionen, OS-Applikationen und Prozessorkerne.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Erfordert mindestens eine Core-Definition (<code>lowerMultiplicity = 1</code>).</li>\n<li>Jeder Core wird über den Integer-Parameter <code>EcucCoreId</code> im Bereich von 0 bis 65535 eindeutig adressiert.</li>\n<li>Partitionierungs- und Modulzuordnungen sind in diesem Diagrammausschnitt nicht enthalten.</li>\n</ul>"}, {"id": "FIG-712812d1f793416b", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR-Konfigurationsmetamodells (ECU Configuration Parameter Definition, EcuC) im Kontext der BSW-Verteilung. Dargestellt ist das Schema zur Zuordnung von Software-Komponenten-Instanzen und BSW-Partitionen zu <code>EcucPartition</code>-Containern sowie deren Verknüpfung mit OS-Applikationen (<code>OsApplication</code>). Core-Definitionen sind nicht Gegenstand dieses Schaubilds.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>EcuC: EcucModuleDef</strong> (Multiplizität: 0..1): Wurzel-Moduldefinition.</li>\n<li>Komposition <code>+container</code> zu <strong>EcucPartitionCollection: EcucParamConfContainerDef</strong> (Multiplizität: 0..1).</li>\n<li><strong>EcucPartitionCollection</strong>: Enthält per Komposition <code>+subContainer</code> <strong>EcucPartition: EcucParamConfContainerDef</strong> (Multiplizität: 0..*).</li>\n<li><strong>EcucPartition</strong>: Repräsentiert eine logische Partition.</li>\n<li>Enthält Referenz <code>+reference</code> <strong>EcucPartitionBswModuleDistinguishedPartition: EcucForeignReferenceDef</strong> (Multiplizität: 0..*, Zieltyp: <code>BSW-DISTINGUISHED-PARTITION</code>), referenziert <code>BswDistinguishedPartition</code> (<code>Referrable</code> aus dem BSW Module Description Template).</li>\n<li>Enthält Instanzreferenz <code>+reference</code> <strong>EcucPartitionSoftwareComponentInstanceRef: EcucInstanceReferenceDef</strong> (Multiplizität: 0..*, Zieltyp: <code>SW-COMPONENT-PROTOTYPE</code>, Zielkontext: <code>ROOT-SW-COMPOSITION-PROTOTYPE</code>), referenziert <code>SwComponentPrototype</code> (<code>AtpPrototype</code> aus dem SW Component Template).</li>\n<li><strong>OsApplication: EcucParamConfContainerDef</strong> (Multiplizität: 0..*): Betriebssystem-Applikationscontainer.</li>\n<li>Enthält Referenz <code>+reference</code> <strong>OsAppEcucPartitionRef: EcucReferenceDef</strong> (Multiplizität: genau 1..1) mit Ziel <code>+destination</code> auf <code>EcucPartition</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Konfigurations-Metamodell ohne dynamische Ausführungssemantik oder Laufzeitsequenzen. Definiert Deklarationsstrukturen zur Entwurfs- und Generierungszeit für das Mapping von BSW- und SWC-Anteilen auf Partitionen, OS-Applikationen und Prozessorkerne.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Jede <code>OsApplication</code> muss über <code>OsAppEcucPartitionRef</code> verpflichtend genau einer <code>EcucPartition</code> zugeordnet sein (Multiplizität 1..1).</li>\n<li><code>EcucPartition</code> enthält in diesem Metamodellausschnitt keine eigenen booleschen Steuerparameter mehr (<code>PartitionCanBeRestarted</code> und <code>EcucDefaultBswPartition</code> fehlen).</li>\n<li>Die Bindung von BSW-Modulen erfolgt unverändert über <code>EcucPartitionBswModuleDistinguishedPartition</code> und die Bindung von SWC-Instanzen über <code>EcucPartitionSoftwareComponentInstanceRef</code>.</li>\n<li>Core-Zuordnungen sind nicht Bestandteil dieses Diagramms.</li>\n</ul>"}], "trans": [{"from": "FIG-8d0b02699e9ce989", "to": "FIG-ae83011d4a502d37", "fr": "R22-11", "tr": "R23-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Referenz <code>OsApplicationCoreRef</code> (Typ <code>EcucReferenceDef</code>) zwischen <code>OsApplication</code> und <code>EcucCoreDefinition</code> entfällt.</li>\n<li>Container <code>EcucCoreDefinition</code>: <code>lowerMultiplicity</code> von <code>0</code> auf <code>1</code> geändert.</li>\n<li>Referenz <code>OsAppEcucPartitionRef</code>: <code>lowerMultiplicity</code> von <code>0</code> auf <code>1</code> geändert.</li>\n</ul>"}, {"from": "FIG-ae83011d4a502d37", "to": "FIG-8a1b20c062d31ec3", "fr": "R23-11", "tr": "R24-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Das Metamodell-Diagramm wurde auf das Fragment von <code>EcucCoreDefinition</code> reduziert; sämtliche Partitionierungs-Elemente entfallen in diesem Schaubild:</li>\n<li><code>EcuC</code> (<code>EcucModuleDef</code>) und <code>EcucPartitionCollection</code> (<code>EcucParamConfContainerDef</code>)</li>\n<li><code>EcucPartition</code> (<code>EcucParamConfContainerDef</code>) nebst Parametern <code>PartitionCanBeRestarted</code> und <code>EcucDefaultBswPartition</code></li>\n<li>Referenzen <code>EcucPartitionSoftwareComponentInstanceRef</code>, <code>EcucPartitionBswModuleDistinguishedPartition</code> und <code>OsAppEcucPartitionRef</code></li>\n<li>Container <code>OsApplication</code> (<code>EcucParamConfContainerDef</code>)</li>\n<li>Externe Vorlagen-Elemente <code>SwComponentPrototype</code> (<code>SW Component Template</code>) und <code>BswDistinguishedPartition</code> (<code>BSW Module Description Template</code>)</li>\n</ul>"}, {"from": "FIG-8a1b20c062d31ec3", "to": "FIG-712812d1f793416b", "fr": "R24-11", "tr": "R25-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Die Partitionierungs-Struktur wird wieder dargestellt, während das Core-Fragment entfällt:</li>\n<li>Container <code>EcucCoreDefinition</code> und Parameter <code>EcucCoreId</code> entfallen.</li>\n<li>Module <code>EcuC</code> (<code>EcucModuleDef</code>) und <code>EcucPartitionCollection</code> (<code>EcucParamConfContainerDef</code>) sind enthalten.</li>\n<li>Container <code>EcucPartition</code> (<code>EcucParamConfContainerDef</code>) mit Referenzen <code>EcucPartitionSoftwareComponentInstanceRef</code>, <code>EcucPartitionBswModuleDistinguishedPartition</code> und <code>OsAppEcucPartitionRef</code> ist enthalten.</li>\n<li>Externe Vorlagen <code>SwComponentPrototype</code> (<code>SW Component Template</code>) und <code>BswDistinguishedPartition</code> (<code>BSW Module Description Template</code>) sind enthalten.</li>\n<li>Container <code>OsApplication</code> (<code>EcucParamConfContainerDef</code>) ist enthalten.</li>\n<li>Die Boolean-Parameter <code>PartitionCanBeRestarted</code> und <code>EcucDefaultBswPartition</code> an <code>EcucPartition</code> entfallen.</li>\n</ul>"}]};
